 */

import { readFileSync, existsSync, writeFileSync } from 'fs';
import { join, dirname } from 'path';
import { fileURLToPath } from 'url';

// Configuration
const THRESHOLD = 20; // Minimum quota percentage (20%)
const FALLBACK_MODEL = 'google/gemini-3-flash-preview';
const AG_PREFIX = 'google-antigravity/';

// Allowed Anti-Gravity model candidates
const CANDIDATES = [
  'google-antigravity/claude-opus-4-5-thinking',
  'google-antigravity/claude-sonnet-4-5',
  'google-antigravity/claude-sonnet-4-5-thinking',
  'google-antigravity/gemini-3-flash',
  'google-antigravity/gemini-3-pro-high',
  'google-antigravity/gemini-3-pro-low',
  'google-antigravity/gpt-oss-120b-medium'
];

// Default file paths (relative to script or provided input dir)
const DEFAULT_STATUS_JSON = 'status.json';
const DEFAULT_STATUS_TXT = 'status.txt';

function parseArgs() {
  const args = process.argv.slice(2);
  const config = {
    inputDir: null,
    threshold: THRESHOLD,
    dryRun: false,
    verbose: false
  };

  for (let i = 0; i < args.length; i++) {
    switch (args[i]) {
      case '--input-dir':
        config.inputDir = args[++i];
        break;
      case '--threshold':
        config.threshold = parseInt(args[++i], 10) || THRESHOLD;
        break;
      case '--dry-run':
        config.dryRun = true;
        break;
      case '--verbose':
      case '-v':
        config.verbose = true;
        break;
      case '--help':
      case '-h':
        printUsage();
        process.exit(0);
    }
  }
  return config;
}

function printUsage() {
  console.log(`Usage: node model-selector.js [options]

Options:
  --input-dir <dir>   Directory containing status files (default: current directory)
  --threshold <n>     Minimum quota percentage for AG models (default: ${THRESHOLD})
  --dry-run           Show decision without updating status.json
  --verbose, -v       Verbose output
  --help, -h          Show this help message

Example:
  node model-selector.js --input-dir ./sample-inputs/test1 --dry-run
`);
}

function readStatusJson(dir) {
  const path = join(dir, DEFAULT_STATUS_JSON);
  if (!existsSync(path)) {
    return null;
  }
  try {
    const content = readFileSync(path, 'utf8');
    return JSON.parse(content);
  } catch (e) {
    console.error(`Error parsing ${path}: ${e.message}`);
    return null;
  }
}

function readStatusTxt(dir) {
  const path = join(dir, DEFAULT_STATUS_TXT);
  if (!existsSync(path)) {
    return null;
  }
  return readFileSync(path, 'utf8');
}

function parseQuotas(statusText) {
  const usageMap = {};

  // Default Gemini models to 100% (infinite quota unless explicitly 0%)
  for (const cand of CANDIDATES) {
    if (cand.includes('gemini')) {
      usageMap[cand] = 100;
    }
  }

  const lines = statusText.split('\n');

  for (const line of lines) {
    // Parse lines like: "  claude-opus-4-5-thinking 18% left"
    const match = line.match(/([a-zA-Z0-9-]+)\s+(\d+)%\s+left/);
    if (match) {
      const modelName = match[1];
      const percent = parseInt(match[2], 10);

      // Add AG prefix if missing
      const fullName = modelName.startsWith(AG_PREFIX) 
        ? modelName 
        : AG_PREFIX + modelName;

      usageMap[fullName] = percent;
    }
  }

  return usageMap;
}

