  let bestModel = null;
  let maxPercent = -1;

  for (const model of CANDIDATES) {
    const percent = usageMap[model] !== undefined ? usageMap[model] : 0;
    if (percent > maxPercent) {
      maxPercent = percent;
      bestModel = model;
    }
  }

  return { bestModel, maxPercent };
}

function makeDecision(currentModel, bestModel, maxPercent, threshold, fallbackModel) {
  const decision = {
    action: 'none',
    selectedModel: currentModel,
    reason: '',
    details: {
      currentModel,
      bestAgModel: bestModel,
      bestAgQuota: maxPercent,
      threshold,
      allAgBelowThreshold: maxPercent < threshold
    }
  };

  if (bestModel && maxPercent >= threshold) {
    // At least one AG model is healthy
    if (currentModel !== bestModel) {
      decision.action = 'switch';
      decision.selectedModel = bestModel;
      decision.reason = `Switching to highest quota AG model: ${bestModel} (${maxPercent}%)`;
    } else {
      decision.action = 'keep';
      decision.selectedModel = currentModel;
      decision.reason = `Current model is optimal: ${currentModel} (${maxPercent}%)`;
    }
  } else {
    // All AG models below threshold - crisis mode
    if (currentModel !== fallbackModel) {
      decision.action = 'fallback';
      decision.selectedModel = fallbackModel;
      decision.reason = `Critical: All AG models below ${threshold}%. Falling back to ${fallbackModel}`;
    } else {
      decision.action = 'keep';
      decision.selectedModel = currentModel;
      decision.reason = `Already on fallback model (AG max: ${maxPercent}%)`;
    }
  }

  return decision;
}

function updateStatusJson(dir, newModel) {
  const path = join(dir, DEFAULT_STATUS_JSON);
  if (!existsSync(path)) {
